import numpy as np
import time


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    N = 26

    def score(state):
        return state[:, 2].sum()

    def build_initial():
        # Hexagonal-ish packing of equal circles as a starting point.
        pts = []
        rows = 6
        cols = 5
        for j in range(rows):
            for i in range(cols):
                if len(pts) >= N:
                    break
                x = (i + 0.5 + 0.5 * (j % 2)) / (cols + 0.5)
                y = (j + 0.5) / rows
                pts.append((x, y))
        while len(pts) < N:
            pts.append((np.random.rand(), np.random.rand()))
        pts = np.array(pts[:N])
        # initial radius small, then relax
        r = np.full(N, 0.01)
        state = np.column_stack([pts, r])
        return state

    def relax(state, iters=200):
        # Force-directed relaxation: push circles apart and to walls, grow radii.
        pos = state[:, :2].copy()
        r = state[:, 2].copy()
        for it in range(iters):
            # grow radii slightly
            r = r * 1.02 + 1e-4
            # clamp radius by walls
            r = np.minimum(r, np.minimum(pos[:, 0], 1 - pos[:, 0]))
            r = np.minimum(r, np.minimum(pos[:, 1], 1 - pos[:, 1]))
            r = np.maximum(r, 1e-4)
            # pair forces
            disp = np.zeros_like(pos)
            for i in range(N):
                for j in range(i + 1, N):
                    d = pos[i] - pos[j]
                    dist = np.hypot(d[0], d[1])
                    overlap = r[i] + r[j] - dist
                    if overlap > 0:
                        if dist < 1e-9:
                            d = np.array([1e-3, 1e-3])
                            dist = np.hypot(d[0], d[1])
                        n = d / dist
                        disp[i] += n * overlap * 0.5
                        disp[j] -= n * overlap * 0.5
            pos += disp * 0.5
            # wall forces + clamp
            for i in range(N):
                if pos[i, 0] - r[i] < 0:
                    pos[i, 0] = r[i]
                if pos[i, 0] + r[i] > 1:
                    pos[i, 0] = 1 - r[i]
                if pos[i, 1] - r[i] < 0:
                    pos[i, 1] = r[i]
                if pos[i, 1] + r[i] > 1:
                    pos[i, 1] = 1 - r[i]
            # shrink radii to satisfy constraints strictly
            for i in range(N):
                r[i] = min(r[i], pos[i, 0], 1 - pos[i, 0], pos[i, 1], 1 - pos[i, 1])
            for i in range(N):
                for j in range(i + 1, N):
                    dist = np.hypot(pos[i, 0] - pos[j, 0], pos[i, 1] - pos[j, 1])
                    if r[i] + r[j] > dist:
                        excess = r[i] + r[j] - dist
                        r[i] -= excess * 0.5
                        r[j] -= excess * 0.5
            r = np.maximum(r, 1e-4)
            if time.process_time() > deadline:
                break
        return np.column_stack([pos, r])

    def refine_greedy(state):
        # Try to grow each radius in turn while keeping feasibility.
        pos = state[:, :2].copy()
        r = state[:, 2].copy()
        order = list(range(N))
        improved = True
        while improved:
            improved = False
            np.random.shuffle(order)
            for i in order:
                if time.process_time() > deadline:
                    return np.column_stack([pos, r])
                maxr = min(pos[i, 0], 1 - pos[i, 0], pos[i, 1], 1 - pos[i, 1])
                for j in range(N):
                    if j == i:
                        continue
                    dist = np.hypot(pos[i, 0] - pos[j, 0], pos[i, 1] - pos[j, 1])
                    maxr = min(maxr, dist - r[j])
                if maxr > r[i] + 1e-7:
                    r[i] = maxr
                    improved = True
        return np.column_stack([pos, r])

    # Try several random restarts and keep the best.
    best = None
    best_score = -1
    np.random.seed(12345)

    if start is not None:
        s = np.asarray(start, dtype=float).copy()
        # validate start; if valid use as candidate
        if s.shape == (N, 3) and np.all(s[:, 2] > 0):
            best = s
            best_score = score(s)

    attempts = 0
    while time.process_time() < deadline:
        attempts += 1
        if start is not None and attempts == 1:
            state = np.asarray(start, dtype=float).copy()
        else:
            state = build_initial()
        state = relax(state, iters=300)
        state = refine_greedy(state)
        sc = score(state)
        if sc > best_score:
            best_score = sc
            best = state.copy()
        if attempts > 50:
            break

    if best is None:
        best = build_initial()

    # Final safety: shrink radii by tiny epsilon to guarantee no violations.
    out = best.copy()
    eps = 1e-9
    out[:, 2] -= eps
    out[:, 2] = np.maximum(out[:, 2], 1e-6)
    # clamp positions
    out[:, 0] = np.clip(out[:, 0], out[:, 2], 1 - out[:, 2])
    out[:, 1] = np.clip(out[:, 1], out[:, 2], 1 - out[:, 2])
    # enforce pair constraints by shrinking
    for i in range(N):
        for j in range(i + 1, N):
            dist = np.hypot(out[i, 0] - out[j, 0], out[i, 1] - out[j, 1])
            if out[i, 2] + out[j, 2] > dist:
                excess = out[i, 2] + out[j, 2] - dist
                out[i, 2] -= excess * 0.5 + 1e-9
                out[j, 2] -= excess * 0.5 + 1e-9
    out[:, 2] = np.maximum(out[:, 2], 1e-6)
    return out

import numpy as np
import time


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80
    N = 26
    rng = np.random.default_rng(12345)

    # ---- core scoring ----
    def total(state):
        return state[:, 2].sum()

    # ---- feasibility: exact check, shrink slightly ----
    def sanitize(state):
        out = state.copy()
        out[:, 2] = np.maximum(out[:, 2], 1e-6)
        # wall clamp
        for i in range(N):
            r = out[i, 2]
            out[i, 0] = min(max(out[i, 0], r), 1 - r)
            out[i, 1] = min(max(out[i, 1], r), 1 - r)
            out[i, 2] = min(out[i, 2], out[i, 0], 1 - out[i, 0],
                            out[i, 1], 1 - out[i, 1])
        # pair constraints
        for i in range(N):
            for j in range(i + 1, N):
                dx = out[i, 0] - out[j, 0]
                dy = out[i, 1] - out[j, 1]
                d = np.hypot(dx, dy)
                s = out[i, 2] + out[j, 2]
                if s > d:
                    ex = s - d
                    out[i, 2] -= ex * 0.5
                    out[j, 2] -= ex * 0.5
        out[:, 2] = np.maximum(out[:, 2], 1e-6)
        return out

    # ---- grow a single radius to its max feasible (given others fixed) ----
    def max_radius(i, pos, r):
        x, y = pos[i]
        m = min(x, 1 - x, y, 1 - y)
        for j in range(N):
            if j == i:
                continue
            d = np.hypot(x - pos[j, 0], y - pos[j, 1])
            m = min(m, d - r[j])
        return m

    # ---- push-apart relaxation at fixed radii, then greedy grow ----
    def relax_and_grow(state, iters):
        pos = state[:, :2].copy()
        r = state[:, 2].copy()
        for it in range(iters):
            if time.process_time() > deadline:
                break
            # pair repulsion
            disp = np.zeros_like(pos)
            for i in range(N):
                for j in range(i + 1, N):
                    dx = pos[i, 0] - pos[j, 0]
                    dy = pos[i, 1] - pos[j, 1]
                    d = np.hypot(dx, dy)
                    ov = r[i] + r[j] - d
                    if ov > 0:
                        if d < 1e-9:
                            dx, dy, d = 1e-3, 1e-3, np.hypot(1e-3, 1e-3)
                        nx, ny = dx / d, dy / d
                        disp[i, 0] += nx * ov
                        disp[i, 1] += ny * ov
                        disp[j, 0] -= nx * ov
                        disp[j, 1] -= ny * ov
            pos += disp * 0.4
            # walls
            for i in range(N):
                pos[i, 0] = min(max(pos[i, 0], r[i]), 1 - r[i])
                pos[i, 1] = min(max(pos[i, 1], r[i]), 1 - r[i])
            # shrink to feasible
            for i in range(N):
                r[i] = min(r[i], pos[i, 0], 1 - pos[i, 0], pos[i, 1], 1 - pos[i, 1])
            for i in range(N):
                for j in range(i + 1, N):
                    d = np.hypot(pos[i, 0] - pos[j, 0], pos[i, 1] - pos[j, 1])
                    if r[i] + r[j] > d:
                        ex = r[i] + r[j] - d
                        r[i] -= ex * 0.5
                        r[j] -= ex * 0.5
            r = np.maximum(r, 1e-4)
        # greedy grow
        order = list(range(N))
        improved = True
        while improved:
            improved = False
            rng.shuffle(order)
            for i in order:
                if time.process_time() > deadline:
                    return np.column_stack([pos, r])
                m = max_radius(i, pos, r)
                if m > r[i] + 1e-9:
                    r[i] = m
                    improved = True
        return np.column_stack([pos, r])

    # ---- initial layouts ----
    def hex_init():
        pts = []
        rows, cols = 6, 5
        for j in range(rows):
            for i in range(cols):
                if len(pts) >= N:
                    break
                x = (i + 0.5 + 0.5 * (j % 2)) / (cols + 0.5)
                y = (j + 0.5) / rows
                pts.append((x, y))
        while len(pts) < N:
            pts.append((rng.random(), rng.random()))
        pts = np.array(pts[:N])
        r = np.full(N, 0.01)
        return np.column_stack([pts, r])

    def random_init():
        pts = rng.random((N, 2))
        r = np.full(N, 0.01)
        return np.column_stack([pts, r])

    # ---- start ----
    best = None
    best_s = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.shape == (N, 3) and np.all(s[:, 2] > 0):
            s = sanitize(s)
            best = s.copy()
            best_s = total(s)

    attempts = 0
    while time.process_time() < deadline:
        attempts += 1
        if attempts == 1 and best is not None:
            state = best.copy()
        elif attempts % 3 == 0:
            state = random_init()
        else:
            state = hex_init()
        state = relax_and_grow(state, iters=250)
        state = sanitize(state)
        sc = total(state)
        if sc > best_s:
            best_s = sc
            best = state.copy()

    if best is None:
        best = sanitize(hex_init())

    # final exact safety
    out = best.copy()
    out[:, 2] = np.maximum(out[:, 2] - 1e-9, 1e-6)
    return sanitize(out)
